import{_ as a,K as i,a as r,c as o,ac as t,b as s,q as n}from"./chunks/framework.BSuaGltH.js";const b=JSON.parse('{"title":"TCP/IP","description":"TCP/IP","frontmatter":{"title":"TCP/IP","description":"TCP/IP","sources":[{"repository":"jekyall_blog","file":"_posts/DevOps/network/2015-10-12-tcpip.md","date":"Thu Aug 22 2019 12:48:54 GMT+0800 (中国标准时间)"}],"showdocs":{"topics":[{"id":"network","title":"网络配置与诊断","link":"/topics/network/"}],"kind":"知识专题","scope":"general","audience":"general","group":"容器与运维","summary":"TCP/IP","status":"active","related":[{"title":"网络：地址、端口、DNS 与基本观察","link":"/systems/network-remote/network/base/basic/start","kind":"知识专题","scope":"general","audience":"general"},{"title":"网络：分层、路由、TCP 与 TLS","link":"/systems/network-remote/network/base/intermediate/mechanisms","kind":"知识专题","scope":"general","audience":"general"},{"title":"网络：离线推演 DNS 与双向路径证据","link":"/systems/network-remote/network/plus/practice/application","kind":"应用实践","scope":"general","audience":"general"},{"title":"网络：能 ping 但业务连接失败的复盘","link":"/systems/network-remote/network/pro/review/review","kind":"知识专题","scope":"general","audience":"general"},{"title":"网络配置与诊断 操作与命令","link":"/systems/network-remote/network/plus/ecosystem/network-general-general","kind":"命令与对象入口","scope":"general","audience":"general"}],"prev":{"text":"OSI 与 TCP/IP 分层笔记","link":"/systems/network-remote/network/plus/subjects/networkengineerbase"},"next":false},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"OSI 与 TCP/IP 分层笔记","link":"/systems/network-remote/network/plus/subjects/networkengineerbase"},"next":false},"headers":[],"relativePath":"systems/network-remote/network/plus/subjects/tcpip.md","filePath":"systems/network-remote/network/plus/subjects/tcpip.md"}'),c={name:"systems/network-remote/network/plus/subjects/tcpip.md"};function p(d,e,u,P,k,h){const l=i("ArticleImage");return r(),o("div",null,[e[0]||(e[0]=t('<h1 id="tcp-ip" tabindex="-1">TCP/IP <a class="header-anchor" href="#tcp-ip" aria-label="Permalink to &quot;TCP/IP&quot;">​</a></h1><h2 id="tcp-ip-1" tabindex="-1">TCP/IP <a class="header-anchor" href="#tcp-ip-1" aria-label="Permalink to &quot;TCP/IP&quot;">​</a></h2><blockquote><p>TCP/IP 协议族包含两个常见传输层协议，传输控制协议(TCP)、用户数据协议(UDP)</p></blockquote><h2 id="tcp——udp" tabindex="-1">TCP——UDP <a class="header-anchor" href="#tcp——udp" aria-label="Permalink to &quot;TCP——UDP&quot;">​</a></h2><ul><li>TCP 数据传输单位 TCP 报文段，UDP 数据传输单位 UDP 报文或者用户数据报</li><li>TCP 面向连接，UDP 面向无连接</li><li>TCP 提供有序可靠的字节流；UDP 自身不保证交付、顺序或去重</li><li>TCP 与 UDP 的性能取决于负载和应用协议，不能仅凭头部复杂性断言传输效率</li></ul><h2 id="tcp" tabindex="-1">TCP <a class="header-anchor" href="#tcp" aria-label="Permalink to &quot;TCP&quot;">​</a></h2><blockquote><p>传输控制协议，面向连接，可靠。一旦数据报被破坏或丢失将会重新传输，TCP 会检测传输错误并予修正，可靠全双工数据传输协议服务</p></blockquote><h3 id="主要功能" tabindex="-1">主要功能 <a class="header-anchor" href="#主要功能" aria-label="Permalink to &quot;主要功能&quot;">​</a></h3><ul><li>数据流的多路复用</li><li>检测数据段完整性</li><li>重新排序</li><li>流量监控</li><li>复杂的时钟机制</li><li>高效的确认方式</li></ul><h3 id="tcp-报文" tabindex="-1">TCP 报文 <a class="header-anchor" href="#tcp-报文" aria-label="Permalink to &quot;TCP 报文&quot;">​</a></h3>',10)),s("p",null,[n(l,{src:"/sources/jekyall_blog/assets/img/network/tcp报文.jpg",alt:"TCP报文信息"})]),e[1]||(e[1]=t('<ul><li>端口号：用来标识同一台计算机的不同的应用进程 <ul><li>源端口：源端口和 IP 地址的作用是标识报文的返回地址</li><li>目的端口：端口指明接收方计算机上的应用程序接口</li></ul></li><li>发送序列号</li><li>确认号</li><li>报头长度</li><li>预留</li><li>编码位 <ul><li>URG：紧急指针</li><li>ACK：确认号有效</li><li>PSH：要求接收端尽快将这个报文交给应用层</li><li>RST：复位一个 TCP 连接</li><li>SYN：同步序列号用于建立连接</li><li>FIN：发送端完成任务并要求终止传输</li></ul></li><li>窗口</li><li>紧急指针</li><li>选项</li><li>填充</li><li>数据</li></ul><h3 id="tcp-三次握手" tabindex="-1">TCP 三次握手 <a class="header-anchor" href="#tcp-三次握手" aria-label="Permalink to &quot;TCP 三次握手&quot;">​</a></h3><p>以下为客户端主动连接、握手报文不携带应用数据的普通情况。x、y 是双方初始序列号；SYN 各占一个序列号，ACK 标志本身不占序号。</p><table tabindex="0"><thead><tr><th>方向</th><th>标志</th><th>seq</th><th>ack</th></tr></thead><tbody><tr><td>客户端 → 服务端</td><td>SYN</td><td>x</td><td>无有效确认号</td></tr><tr><td>服务端 → 客户端</td><td>SYN, ACK</td><td>y</td><td>x+1</td></tr><tr><td>客户端 → 服务端</td><td>ACK</td><td>x+1</td><td>y+1</td></tr></tbody></table><p>确认号表示期望收到的下一个序号，不是“对端序号加随机数”。例如 x=100、y=300，后两次确认分别为 101 和 301。依据 <a href="https://www.rfc-editor.org/rfc/rfc9293.html#section-3.5" target="_blank" rel="noopener noreferrer">RFC 9293 三次握手</a>。</p><h3 id="四次挥手" tabindex="-1">四次挥手 <a class="header-anchor" href="#四次挥手" aria-label="Permalink to &quot;四次挥手&quot;">​</a></h3><ul><li><p>客户端发送---------------------FIN，ACK----------------------------&gt;服务端</p><blockquote><p>FIN（终止传输）、ACK（确认收到最后一个包）</p></blockquote></li><li><p>客户端&lt;--------------------------ACK-------------------------------------服务端发送</p><blockquote><p>ACK（确认收到）</p></blockquote></li><li><p>客户端&lt;--------------------------FIN--------------------------------------服务端发送</p><blockquote><p>FIN（终止发送）</p></blockquote></li><li><p>客户端发送----------------------ACK-----------------------------------&gt;服务端</p><blockquote><p>ACK（确认终止发送）</p></blockquote></li></ul><h2 id="udp" tabindex="-1">UDP <a class="header-anchor" href="#udp" aria-label="Permalink to &quot;UDP&quot;">​</a></h2>',8))])}const C=a(c,[["render",p]]);export{b as __pageData,C as default};
